function icon(name: string, size = ""): string { return `<svg class="icon ${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name] || iconPaths.spark}</svg>`; }
function brand(extra = ""): string { return `<a class="brand ${extra}" href="/" data-route><svg class="brand-symbol" viewBox="0 0 48 48" aria-hidden="true"><rect width="48" height="48" rx="15" fill="#173B2B"/><text x="24" y="32" text-anchor="middle" fill="#D7FF58" font-family="Onest, Arial, sans-serif" font-size="19" font-weight="800" letter-spacing="-3">ББ</text></svg><span class="brand-name">Блиц Банк</span></a>`; }
function arrowLink(path: string, label: string): string { return `<a class="text-link" href="${path}" data-route>${label} ${icon('arrow','icon-sm')}</a>`; }
function button(path: string, label: string, cls = "btn-primary"): string { return `<a class="btn ${cls}" href="${path}" data-route>${label}<span aria-hidden="true">↗</span></a>`; }
function cardMock(variant = "lime"): string { return `<div class="bank-card ${variant}"><div class="card-top"><span>Блиц Банк</span><span class="card-mark">ББ</span></div><div class="chip"></div><div class="card-bottom"><span>•••• &nbsp;•••• &nbsp;•••• &nbsp;4831</span><span>МИР</span></div></div>`; }
function breadcrumb(items: [string, string?][]): string { return `<nav class="breadcrumbs" aria-label="Навигационная цепочка">${items.map((x,i)=>`${i?'<span>›</span>':''}${x[1]?`<a href="${x[1]}" data-route>${x[0]}</a>`:`<b>${x[0]}</b>`}`).join('')}</nav>`; }
function formatMoney(value: number, compact = false): string {
  const val = Math.round(Number(value)||0);
  const str = new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(val);
  if (!compact) return `${str} ₽`;
  if (Math.abs(val)>=1000000) return `${new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(val/1000000)} млн ₽`;
  if (Math.abs(val)>=1000) return `${new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(val/1000)} тыс. ₽`;
  return `${str} ₽`;
}
function escapeHTML(s: string): string { const replacements: Record<string, string> = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }; return String(s).replace(/[&<>"']/g, (character) => replacements[character] ?? character); }

