function searchPanel(): string {
  const items = Object.entries(PAGES)
    .filter(([path, page]) => !path.startsWith('/app') && page.kind !== 'login')
    .map(([path, page], order) => {
      const alias = Object.entries(searchAliases).find(([prefix]) => path.startsWith(prefix))?.[1] ?? '';
      const searchable = `${page.title} ${page.desc} ${page.eyebrow} ${path} ${alias}`.toLocaleLowerCase('ru-RU').replaceAll('ё', 'е');
      return `<a class="search-result" href="${path}" data-route data-search-entry data-search-order="${order}" data-search-text="${escapeHTML(searchable)}" hidden><span><strong>${escapeHTML(page.title)}</strong><small>${escapeHTML(page.eyebrow)}</small></span>${icon('arrow','icon-sm')}</a>`;
    }).join('');

  return `<div class="site-search-panel" id="site-search-panel" aria-hidden="true"><div class="wrap site-search-inner"><label class="site-search-field">${icon('search')}<input id="site-search-input" type="search" autocomplete="off" placeholder="Например, дебетовая карта" aria-label="Поиск по сайту"><button class="search-close" type="button" data-search-close aria-label="Закрыть поиск">${icon('close')}</button></label><p class="search-status" id="search-status" role="status" aria-live="polite">Введите название продукта или услуги</p><div class="search-results" id="search-results">${items}</div></div></div>`;
}
