  if (path==='/documents/tariffs') return `<section class="section-tight"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Ключевые цифры</p><h2>Тарифы в одном месте</h2><p>Основные условия карт, вкладов и кредитов «Блиц Банка».</p></div></div><div class="table-wrap"><table class="compare-table"><thead><tr><th>Продукт</th><th>Обслуживание</th><th>Ключевое условие</th><th>Подробности</th></tr></thead><tbody><tr><td>Дебетовая карта «Блиц»</td><td>0 ₽</td><td>До 5% в категориях</td><td><a href="/cards/debit/blitz" data-route>К карте →</a></td></tr><tr><td>Кредитная карта «Блиц 120»</td><td>0 ₽</td><td>До 120 дней</td><td><a href="/cards/credit/blitz-120" data-route>К карте →</a></td></tr><tr><td>Вклад «Блиц»</td><td>Без платы по тарифу</td><td>До 14,5% годовых</td><td><a href="/deposits/blitz" data-route>К вкладу →</a></td></tr><tr><td>Кредит наличными</td><td>По договору</td><td>От 17,9% в расчёте</td><td><a href="/loans/cash" data-route>К расчёту →</a></td></tr></tbody></table></div><p class="disclosure" style="margin-top:16px">Основные условия продуктов, ставки и комиссии указаны в тарифах.</p></div></section>`;
  if (path==='/legal/offer') return `<section class="section-tight"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Правовая информация</p><h2>Условия использования</h2><p>Основные правила работы с сайтом и его сервисами.</p></div></div><div class="surface" style="padding:28px;max-width:900px"><h3>1. Общие положения</h3><p class="muted">Используя сервисы Блиц Банка, пользователь подтверждает, что ознакомился с условиями обслуживания и обязуется предоставлять корректные сведения.</p><h3>2. Безопасность</h3><p class="muted">Не передавайте третьим лицам пароли, коды подтверждения и реквизиты банковских карт. При подозрении на несанкционированный доступ немедленно обратитесь в службу поддержки.</p><h3>3. Продукты и тарифы</h3><p class="muted">Ставки, комиссии, сроки и ограничения приведены в тарифах соответствующих продуктов. Перед оформлением внимательно ознакомьтесь с условиями.</p><h3>4. Обращения</h3><p class="muted">По вопросам обслуживания обратитесь в чат поддержки или выберите подходящий способ связи в разделе контактов.</p></div></div></section>`;
  if (path==='/legal/privacy') return `<section class="section-tight"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Конфиденциальность</p><h2>Ваши данные под защитой</h2><p>Рассказываем, какие сведения нужны и как бережно с ними обращаться.</p></div></div><div class="benefit-grid"><article class="benefit"><span class="product-icon">Б</span><h3>Персональные данные</h3><p>Персональные данные клиентов защищены в цифровых сервисах банка.</p></article><article class="benefit"><span class="product-icon">Б</span><h3>Безопасность</h3><p>Не сообщайте пароли, коды подтверждения и реквизиты карты в чате или по телефону.</p></article><article class="benefit"><span class="product-icon">Б</span><h3>Обращения</h3><p>По вопросам обработки персональных данных свяжитесь со службой поддержки.</p></article></div></div></section>`;
