function primaryAction(path: string, page: PageMeta): string {
  if (path === '/online-bank' || path === '/transfers') return '';
  const links: Record<string, [string, string]> = {
    '/documents':['/documents/tariffs','Открыть тарифы'],
    '/about':['/cards/debit','Посмотреть продукты'],
    '/about/news':['/cards/debit','Вернуться к продуктам'],
    '/about/careers':['/about','О команде'],
    '/contacts':['/help','Открыть центр помощи'],
    '/help':['/contacts','Написать в поддержку']
  };
  if(links[path]) return `<a class="btn btn-primary" href="${links[path][0]}" data-route>${links[path][1]} <span>↗</span></a>`;
  if(path==='/atms') return `<a class="btn btn-primary" href="#map-points">Показать точки <span>↓</span></a>`;
  return `<button class="btn btn-primary" data-action="apply">${page.cta} <span>↗</span></button>`;
}

function renderGeneric(path: string, page: PageMeta): string {
  if (page.kind==='catalog') return renderCatalog(path,page);
  if (page.kind==='compare') return renderCompare(page);
  const parents: [string, string?][] = [['Главная','/']];
  if (path.startsWith('/cards')) parents.push(['Карты','/cards/debit']);
  else if (path.startsWith('/loans') || path==='/mortgage') parents.push(['Кредиты','/loans']);
  else if (path.startsWith('/deposits') || path==='/savings') parents.push(['Накопления','/deposits']);
  else if (path.startsWith('/investments')) parents.push(['Инвестиции','/investments']);
  else if (path.startsWith('/business')) parents.push(['Бизнесу','/business']);
  else if (path.startsWith('/about')) parents.push(['О банке','/about']);
  else if (path.startsWith('/legal') || path.startsWith('/documents')) parents.push(['Документы','/documents']);
  parents.push([page.title]);
  const points=pointSets[page.kind]||pointSets.service;
  const facts: [string, string][] = page.facts || [[page.metric,page.note],['24/7','доступ на странице'],['Понятно','условия рядом'],['Удобное управление','Основные сервисы доступны в приложении.']];
  const showTerms = Boolean(page.facts) && path !== '/savings';
  const termsDisclosure = page.kind === 'credit'
    ? '<p class="disclosure" style="margin-top:18px">При выходе за границы льготного периода начисляются проценты в соответствии с тарифом. Минимальный платёж и даты указаны в мобильном приложении.</p>'
    : '';
  const extra=specialSections(path);
  const action = primaryAction(path,page);
  return publicShell(`<main><section class="product-hero"><div class="wrap">${breadcrumb(parents)}<div class="product-hero-grid"><div><h1>${page.title}</h1><p class="lead">${page.desc}</p>${action ? `<div class="btn-row">${action}</div>` : ''}<div class="feature-list">${points.slice(0,2).map(([t])=>`<div class="feature-point"><span class="check">✓</span><span>${t}</span></div>`).join('')}</div></div><div class="product-art ${page.kind==='credit'||page.kind==='business'||page.kind==='legal'?'dark':''}">${artFor(page)}</div></div>${page.kind==='legal'||page.kind==='document'?'':`<div class="fact-row">${facts.slice(0,4).map(([v,l])=>`<div class="fact"><strong>${v}</strong><span>${l}</span></div>`).join('')}</div>`}</div></section>
  ${calcBlock(page.kind)}
  ${showTerms ? `<section class="section-tight" style="background:#EDF2E9"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Условия</p><h2>Коротко о главном</h2><p>Проверьте ключевые цифры и ограничения до следующего шага.</p></div></div><div class="term-grid">${termsFor(page).map(([label,val])=>`<div class="term-box"><span>${label}</span><strong>${val}</strong></div>`).join('')}</div>${termsDisclosure}</div></section>` : ''}
  ${extra}
  ${path==='/help' ? `<section class="section-tight"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Вопросы и ответы</p><h2>Что важно знать</h2></div></div>${faqList(faqFor(page))}</div></section>` : ''}</main>`);
}
function termsFor(page: PageMeta): [string, string][] {
  if (page.kind==='card') return [['Обслуживание','0 ₽'],['Базовый кешбэк','1,5%'],['Категории','до 5%'],['Лимит возврата','до 5 000 ₽ / мес.'],['Пополнение','без комиссии'],['Снятие наличных','условия зависят от тарифа']];
  if (page.kind==='credit') return [['Кредитный лимит','до 450 000 ₽'],['Льготный период','до 120 дней'],['Обслуживание','0 ₽'],['Ставка после периода','29,9–59,9% годовых'],['Минимальный платёж','5% от долга'],['Досрочное погашение','без штрафа']];
  if (page.kind==='mortgage') return [['Ставка по ипотеке','13,9% годовых'],['Первоначальный взнос','от 20%'],['Срок','до 30 лет'],['Платёж','аннуитетный'],['Оценка недвижимости','не включена'],['Полная стоимость','уточняется в договоре']];
  if (page.kind==='loan') return [['Сумма','до 5 млн ₽'],['Срок','до 7 лет'],['Ставка годовых','от 17,9%'],['График','аннуитетный'],['Досрочное погашение','по условиям договора'],['Залог','не требуется']];
  if (page.kind==='deposit') return [['Ставка по вкладу','14,5% годовых'],['Срок','3–24 месяца'],['Пополнение','по условиям продукта'],['Капитализация','ежемесячно'],['Минимальная сумма','от 10 000 ₽'],['Доход','не гарантируется']];
  if (page.kind==='business') return [['Открытие счёта','1 день'],['Первые 2 месяца','0 ₽'],['Платежи','по выбранному тарифу'],['Команда','несколько ролей'],['Эквайринг','от 1,3%'],['Данные','в приложении для бизнеса']];
  return [['Условия','на странице продукта'],['Оформление','доступно онлайн'],['Персональные данные','защищены'],['Платежи','после подтверждения'],['Данные','в приложении']];
}
function notFound() { return publicShell(`<main class="not-found"><div><div class="code">404</div><p class="eyebrow" style="margin-top:20px">Такой страницы нет</p><h1 style="font-size:38px">Похоже, маршрут потерялся</h1><p class="lead" style="margin-inline:auto">Вернитесь на главную или откройте нужный раздел в меню.</p><div class="btn-row" style="justify-content:center"><a class="btn btn-primary" href="/" data-route>На главную</a><a class="btn btn-quiet" href="/help" data-route>Центр помощи</a></div></div></main>`); }


export function renderLegacyPage(path: string): string {
  const html = path === '/' ? homepage() : PAGES[path] ? renderGeneric(path, PAGES[path]) : notFound();
  const basePath = process.env.NEXT_PUBLIC_BASE_PATH || '';
  return basePath ? html.replaceAll('href="/', `href="${basePath}/`) : html;
}

export function getLegacyPageMetadata(path: string): { title: string; description: string } {
  if (path === '/') return { title: 'Блиц Банк — банк на твоей скорости', description: 'Карты, накопления, переводы и финансовые сервисы для повседневных задач.' };
  const page = PAGES[path];
  return {
    title: `${page?.title || 'Страница не найдена'} — Блиц Банк`,
    description: page?.desc || 'Блиц Банк — финансовые продукты и сервисы для повседневных задач.'
  };
}


export function getLegacyMenuGroups(): Record<string, MenuGroup> {
  return menuGroups;
}

export const legacyPagePaths: string[] = Object.keys(PAGES);
